/**
 * Test flow for Run Once trigger
 * Tests: One-time scheduled trigger at specific date/time
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testRunOnceTrigger = Flow(
    {
        $id: Now.ID['test_run_once_trigger_flow'],
        name: 'Test Run Once Trigger',
        description: 'Tests the Run Once trigger executing at specific date/time',
    },
    wfa.trigger(
        trigger.scheduled.runOnce,
        { $id: Now.ID['test_run_once_trigger'] },
        {
            run_in: '2025-12-31 23:59:00',
        }
    ),
    (_params) => {
        // Log trigger outputs
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_run_once_trigger_log'] },
            {
                log_level: 'info',
                log_message: `Run-Once Trigger - Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)
